import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十五卦 謙 地山謙 坤上艮下","description":"周易 - 第十五卦 謙 地山謙 坤上艮下","frontmatter":{"title":"第十五卦 謙 地山謙 坤上艮下","description":"周易 - 第十五卦 謙 地山謙 坤上艮下"},"headers":[],"relativePath":"classics/zhouyi/016.md","filePath":"classics/zhouyi/016.md"}'),l={name:"classics/zhouyi/016.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="謙" tabindex="-1">謙 <a class="header-anchor" href="#謙" aria-label="Permalink to “謙”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，君子有終。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>謙，亨，天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可踰，君子之終也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>地中有山，謙；君子以裒多益寡，稱物平施。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>謙謙君子，用涉大川，吉。 象曰：謙謙君子，卑以自牧也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>鳴謙，貞吉。象曰：鳴謙貞吉，中心得也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>勞謙君子，有終吉。象曰：勞謙君子，萬民服也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>無不利，(扌為)謙。象曰：無不利，(扌為)謙；不違則也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>不富，以其鄰，利用侵伐，無不利。象曰：利用侵伐，徵不服也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>鳴謙，利用行師，徵邑國。象曰：鳴謙，志未得也。可用行師，徵邑國也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
